"Anyone remember why the sky is a portal?":"Weiß noch jemand, warum der Himmel ein Portal ist?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Es heißt, wer in den Schacht springt, landet beim Feind. Teste ich nicht.",
"The Swarm painted their visors red again. Show-offs.":"Der Schwarm hat seine Visiere wieder rot lackiert. Angeber.",
"Ore, ore… when do we get some oil?":"Erz, Erz … wann gibt's mal Schmieröl?",
"I dreamt I was a toaster. It was peaceful.":"Ich hab geträumt, ich wäre ein Toaster. Es war friedlich.",
"Quiet. Too quiet.":"Ruhig. Zu ruhig.",
"See that? Our base is above the Swarm base again. Portals, man.":"Seht ihr das? Über der Schwarm-Basis ist wieder unsere Basis. Portale, Mann.",
"Diman, if you're reading this — we need a vacation.":"Diman, falls du das liest — wir brauchen Urlaub.",
