"Autosaved":"Automatisch gespeichert",
"robot war · the sky is a portal":"Roboterkrieg · der Himmel ist ein Portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Willkommen auf dem Meteor! Du bist ein Kampfroboter des Konsortiums. Sieh dich mit der Maus um und lauf mit WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: Tippe Shift für einen Hüpfer, halte Shift zum Fliegen. Die Energie lädt sich am Boden wieder auf.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Feuern — linke Maustaste. Zielen — rechte Maustaste: genauer, mit Zoom. Gib ein paar Schüsse ab.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Nachladen — R. Kugeln treffen auf mittlere Distanz, 20–50 Meter, am härtesten.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rakete — Q. Gegen Panzer und Gebäude. Feuere eine Rakete ab.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Oben steht die Aufgabe des Strategen. Lauf den grünen Pfeilen nach: Auf der Route sprintest du. Kontrollpunkt einnehmen — bleib in der Nähe der Bake.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Dein Trupp gibt dir Deckung: Links siehst du Porträts und Gesundheit. Fällt der Trupp zurück, bitten sie dich zu warten.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — schneller Einheitenwechsel mitten im Gefecht: Spring in den Trupp oder Panzer, der dem Kampf am nächsten ist. Probier es aus.",
"Next to a tank or turret press E to take control. Or just carry on.":"Neben einem Panzer oder Geschützturm drückst du E, um die Kontrolle zu übernehmen. Oder geh einfach weiter.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Jetzt die Strategie. Tippe oben rechts auf „◩ Strategie“ — eine Draufsicht auf das Schlachtfeld.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Jetzt die Strategie. Drücke {0} (oder oben links „◩ Strategie“) — eine Draufsicht auf das Schlachtfeld.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"In der Strategie hilft dir der Kurator: Das Fenster oben sagt, was zu tun ist, ein Rahmen zeigt die Schaltfläche, ein Ring markiert die Stelle auf der Karte. Erfülle drei seiner Tipps.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Wähle einen Trupp und tippe auf die grüne Schaltfläche „▶ Übernehmen“ — zurück in den Kampf als dieser Soldat. Während du schießt, führt der KI-Stratege die Armee.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Wähle einen Trupp und drücke {0} oder das grüne „▶ Übernehmen“ — zurück in den Kampf als dieser Soldat (ohne Auswahl — dein eigener). Während du schießt, führt der KI-Stratege die Armee.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Training abgeschlossen! Der Schwarm beginnt seine Offensive. Viel Glück, Soldat!",
