"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"Dann klick (tippe) auf den Boden: Sie rücken vor und kämpfen unterwegs. Auf einen Feind — ihn angreifen. Wie rechte Maustaste.",
