"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Steuere den ausgewählten Soldaten, Panzer oder Geschützturm selbst. Dieselbe Taste im Kampf bringt dich zurück zur Strategie.",
