"New in v6.3":"Neu in v6.3",
"New in v6.2":"Neu in v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Neues Erz-Aussehen: Adern sind leuchtende, facettierte Smaragdkristalle auf schwarzem Basalt mit Funken und grünem Dunst; der Extraktor ist ein sechseckiger Sockel mit Wabenkuppel und einem Gitterturm mit grünem Leuchtfeuer (Streifen und Wimpel in Teamfarbe)",
"New in v6.1":"Neu in v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Bevorzugte Klasse wie in Battlefield (U, Zahlen nach dem Tod): Du startest damit neu, wenn sie verfügbar ist",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Fahrzeuge in der Ich-Perspektive (V — außen/Kabine); sanfte Zielhilfe — in den Einstellungen",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Leichter Ausstieg aus dem Kern: Leertaste — zum Schacht, B — Kapsel an die Oberfläche; Fähigkeitseffekte werden beim Tod zurückgesetzt",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Endlose Progression: Generäle und Marschall ★, Karrierestufen, Waffenmeisterschaft und Aufsätze, Medaillen, Tagesaufträge — Bildschirm „Karriere“",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategie: sanfter Mausrad-Zoom, Symbole und Beschriftungen über den Einheiten (Alt — alle), Panel „Truppen / Gebäude“ links",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"RMB — Angriffsmarsch, doppelter RMB — Marsch mit Feuer im Gehen; seltene Befehle unter „Mehr Befehle ▾“; keine doppelten Buttons",
"New in v6":"Neu in v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Shooter-Waffengefühl: Treffer ohne Verzögerung, Gewehr mit 720 Schuss/min, MG, Rückstoß, Zielen mit RMB, Magazine und Nachladen mit R, Trefferanzeigen",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Schwerere Gravitation, direkteres Jetpack, Dash mit Z oder doppeltem Jet in der Luft; beim Einheitenwechsel fliegt die Waffe nicht mehr mit",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Ingenieure: Ingenieur wählen, Gebäude aussuchen, Bauplan platzieren; Extraktoren auf Erzadern; Klick auf „ERZ“ zeigt Einkommen und wie du es steigerst",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Graue Buttons erklären das Warum und bieten eine Lösung an; größere Buttons, Leiste „In Arbeit“, „▶ Übernehmen“, Tab ist die eine Modustaste",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strategiekamera ohne Sprünge und Überschläge, Zoom zum Cursor, Minimap ziehbar",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Neue Fahrzeuge: Raider „Jackal“, Raketenwerfer „Grad“ (zielsuchende Raketen), Mörser „Hammer“; der Schwarm bekommt „Wasp“, „Hive“, „Trebuchet“",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Der Stratege lässt Befehle in Ruhe und spammt keine Sprachausgabe mehr; Kämpfe finden bei dir statt; B — Verlegung, Shift+B — mitten ins Gefecht; Kompass, H — welches Ziel",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Freies Spiel (K) und Alleingang (J), F2 — Voreinstellungen; Esc pausiert und setzt fort; Speichern: Slots, Export und Import",
"New in v5.3":"Neu in v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Flug: stärkere Schwerkraft fern des Meteors, C in der Luft bremst, Schub lenkt schärfer; kein Hängenbleiben mehr im Portal",
