"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"Granate ({0}): halten — Flugbogen, Explosionspunkt und -kreis, Entfernung; loslassen — Wurf; kurzes Tippen wirft sofort. Reichweite per Blickwinkel, Rad — Kraft, RMB — vor die Füße. Handy: G gedrückt halten und ziehen.",
