"Builders are trained at the HQ — its panel is open on the right":"Baumeister werden im Hauptquartier ausgebildet — sein Panel ist rechts geöffnet",
"pick a building → tap a spot → \"Build\"":"Gebäude wählen → Stelle antippen → „Bauen“",
"pick a building → LMB on a spot (Shift — several)":"Gebäude wählen → linke Maustaste auf eine Stelle (Shift — mehrere)",
"The selected builders do the building. RMB on your building — repair.":"Gebaut wird von den gewählten Baumeistern. Rechte Maustaste auf dein Gebäude — Reparatur.",
"Select a builder to build":"Wähle einen Baumeister zum Bauen",
"Only builders construct. Click a builder on the map or press the button.":"Nur Baumeister bauen. Klicke auf der Karte auf einen Baumeister oder drücke die Schaltfläche.",
"No builders: select the HQ and train a builder.":"Keine Baumeister: Wähle das Hauptquartier und bilde einen Baumeister aus.",
"Select nearest builder":"Nächsten Baumeister wählen",
"HQ: train a builder":"Hauptquartier: Baumeister ausbilden",
"Build keys (Z X C V B N K) pick the nearest builder automatically.":"Die Bautasten (Z X C V B N K) wählen automatisch den nächsten Baumeister.",
"Pick a building to open its production. Or click a building on the map.":"Wähle ein Gebäude, um seine Produktion zu öffnen. Oder klicke auf der Karte auf ein Gebäude.",
"building {0}%":"Bau {0}%",
"queue {0}":"Warteschlange {0}",
"New production buildings are built by builders (\"Build\" tab).":"Neue Produktionsgebäude werden von Baumeistern gebaut (Reiter „Bauen“).",
"Previous building":"Vorheriges Gebäude",
