"The HQ is already building an upgrade":"Das Hauptquartier baut bereits eine Verbesserung",
"HQ: {0} ready":"Hauptquartier: {0} fertig",
"HQ: {0} online":"Hauptquartier: {0} einsatzbereit",
"Intel: the Swarm HQ got \"{0}\"":"Aufklärung: Das Hauptquartier des Schwarms hat „{0}“ erhalten",
