"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapsel auf Punkt {0}: {1}{2}{3}. Der Baumeister kann einen Außenposten errichten (V) und einen Verbesserungszweig wählen.",
