"Outpost upgrades":"Verbesserungen des Außenpostens",
"point":"Punkt",
"Pick a branch — every point gets its own speciality:":"Wähle einen Zweig — jeder Punkt hat seine eigene Spezialisierung:",
"Building — click to cancel":"Wird gebaut — Klick: abbrechen",
"A builder near the outpost (30 m) does the upgrade.":"Ein Baumeister in der Nähe des Außenpostens (30 m) führt die Verbesserung aus.",
"Send a builder":"Baumeister schicken",
"Builders nearby":"Baumeister in der Nähe",
"{0} is heading to the outpost":"{0} geht zum Außenposten",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Von Anfang an steht in deiner Basis die ganze Armee, je eine Einheit: Fallschirmjäger, einzelner Schwerschütze, Scharfschütze, Späher, Drohne, Raider, Raketenwerfer, Mörser (dazu Sturmtrupps und ein Panzer) — übernimm sofort jeden",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"„Eigene Reihenfolge“ für das Übernehmen (Pausenmenü, ☰ am Handy): Jede Klasse hat eine Nummer, 1 ist die höchste; ▲▼ ändern sie, ✕ heißt nie. Nach dem Tod und mit X bekommst du in dieser Reihenfolge die Einheit, die dem Kampf am nächsten ist",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Bots sind keine Scharfschützen mehr: Sie verfehlen auf Distanz, in Bewegung, bei Läufern und Zielen in Deckung; Kugeln pfeifen an dir vorbei und schlagen neben dir in Boden und Deckung. Explosionen werfen dich um: Zucken, auf ein Knie, von den Füßen und wieder hoch",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Erobere einen Punkt, und eine Kapsel setzt einen Trupp und einen Baumeister ab. Ein Außenposten auf dem Punkt wird entlang eines Zweigs ausgebaut: Verteidigung (MG-Bunker → schwerer Bunker mit Panzerabwehrkanone), Unterstützung (Reparaturdrohnen → Schutzfeldkuppel), Aufklärung (Funkscanner → Scharfschützen- und Aufklärungsturm)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Auch das Hauptquartier wird ausgebaut: Panzerplatten, Verteidigungstürme, schnellerer Orbitalabwurf, +25 % Einkommen, globaler Radar, Kommunikationsantennen (+Kommandopunkte). Die KI macht dasselbe",
"New in v7.0":"Neu in v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"In der Basis steht je eine Einheit und ein Fahrzeug jedes Typs: Fallschirmjäger, Scharfschütze, Späher, Drohne, Raider, Raketenwerfer, Mörser. Wähle einen aus und {0} — probier sie aus, bevor du gebaut hast.",
"POSSESS":"ÜBERNEHMEN",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Punkt {0}: Mit der Kapsel ist ein Baumeister gelandet. Wähle ihn aus und errichte einen „Außenposten“{1} am Punkt – danach wählst du einen Verbesserungszweig.",
"OUTPOST":"AUSSENPOSTEN",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Der Außenposten ist fertig – wähle ihn aus und such einen Zweig aus: ⛨ Verteidigung (MG-Bunker, Panzerabwehrbunker), ✚ Unterstützung (Reparaturdrohnen, Schutzfeldkuppel) oder ◎ Aufklärung (Scanner, Scharfschützenturm). Ein Baumeister in der Nähe baut.",
"UPGRADE":"AUSBAUEN",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Das Hauptquartier ist ein „Superpunkt“: Wähle es aus{0} — Panzerplatten, Türme, schnellerer Abwurf, +25 % Einkommen, Radar, Kommunikation.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → „Übernehmen“: Schalte „Eigene Reihenfolge“ ein und bestimme, wen du nach dem Tod übernimmst — Nr. 1, Nr. 2… ✕ heißt nie.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → Pause → „Eigene Reihenfolge“: Bestimme, wen du nach dem Tod und mit X übernimmst — Nr. 1, Nr. 2… ✕ heißt nie.",
"🛠 HQ: all upgrades":"🛠 Hauptquartier: alle Verbesserungen",
"🛠 Outpost with \"{0}\" (II) nearby":"🛠 Außenposten mit Zweig „{0}“ (II) in der Nähe",
