"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Der Ingenieur ist gewählt — tippe unten auf seiner Karte auf „◆ Kristalle abbauen“ (oder tippe auf die grünen Kristalle).",
