"steps":"Schritte",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Du kannst eine Basis bauen, Truppen bestellen, kommandieren und in den Kampf springen. Weiter geht's mit einem echten Match: Der Kurator hilft dir unterwegs.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Du kannst dich bewegen, fliegen, schießen, in Deckung gehen und deinen Trupp kommandieren. Weiter geht's mit einem echten Match.",
