"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Eine sichere Spielwiese: Feinde sind reglose Puppen, niemand schießt auf dich. Ein Schritt zählt nur, wenn du die Aktion wirklich selbst ausführst.",
"Show others (training for the other device)":"Andere zeigen (Training für das andere Gerät)",
"Old training (v7.1)":"Altes Training (v7.1)",
"Back to the normal device mode":"Zurück zum normalen Gerätemodus",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Das Training für das andere Gerät lädt die Seite in dessen Modus neu (PC — Maus und Tastatur, Handy — Touch; am PC kannst du Touch bequem in Chrome testen: F12 → Handy-Symbol).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Training ×4: separate Schritt-für-Schritt-Lektionen „Strategie\" und „Schütze\" für PC und Handy. Eine sichere Sandbox mit Attrappen, hervorgehobene richtige Taste, Pfeile, animierte Tasten, Maus und Gesten; ein Schritt zählt nur bei echter Aktion, „Schritt wiederholen\", Fortschritt oben und eine Belohnung am Ende",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Das Training-Menü zeigt die Lektionen für dein Gerät; „Andere zeigen\" — alle vier auf jedem Gerät; das „Alte Training (v7.1)\" gibt es weiterhin",
"New in v7.2":"Neu in v7.2",
"NEW IN v7.2":"NEU IN v7.2",
"No grenades left":"Keine Granaten mehr",
"Rocket and grenade recharging · {0} s":"Rakete und Granate laden auf · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Links — bewegen, rechts — umsehen · Tippen auf Gegner — Rakete / Granate · 2× Tippen — Reflex · 3× Tippen — Artillerieschlag",
"Less":"Weniger",
"More":"Mehr",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Gegnerisches Fahrzeug oder Gebäude in der Nähe — tippe darauf: Eine Rakete fliegt los.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Viele Feinde — tippe zweimal schnell auf eine freie Stelle rechts: Reflex verlangsamt die Zeit.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Ziele auf die Gegneransammlung und tippe 3× — Artillerieschlag.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Linker Daumen — bewegen, rechter — umsehen. Feuert von selbst, wenn du auf einen Gegner zielst.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ am linken Rand — Jetpack: Tippen zum Hüpfen, Halten zum Fliegen.",
"Old v7.2 layout":"Altes v7.2-Layout",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Zieh mit dem Finger über die rechte Bildschirmhälfte — unter dem Finger erscheint ein Blickstick.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Berühre die linke Seite und zieh — unter dem Finger erscheint ein Stick. Erreiche die grüne Markierung.",
"Hold the \"Jet\" button at the left edge.":"Halte die Taste „Jetpack\" am linken Rand.",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Ziele mit dem rechten Stick auf eine Attrappe — dein Soldat feuert von selbst, wenn das Fadenkreuz auf dem Ziel liegt.",
"Tap the dummy on the screen — a rocket flies.":"Tippe auf die Attrappe auf dem Bildschirm — eine Rakete fliegt los.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Tippe auf die Attrappe — eine Granate fliegt im Bogen genau dorthin.",
"Double tap an empty spot on the right quickly.":"Tippe schnell zweimal auf eine freie Stelle rechts.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Lite-Modus für schwache Handys: niedrigere Auflösung, keine Schatten oder Verzerrung, halb so viele Bots und Partikel, maximal 30 FPS; senkt die Auflösung selbst, wenn FPS < 25. Auf Handys standardmäßig an (Einstellungen → Grafik → „Lite-Modus\"; oder ?lite=1 / ?lite=0 im Link).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Handy: neues Layout. Links — bewegen, rechts — umsehen (beide Sticks erscheinen unter dem Finger). Nur der linke Daumen — „Auto\"; ist der rechte im Einsatz, feuert der Soldat nur von selbst, solange das Fadenkreuz auf einem Gegner liegt. Tippen auf Gegner — Rakete oder Granate, 2× Tippen — Reflex, 3× Tippen — Artillerieschlag. Automatisches Nachladen. Jetpack — Taste am linken Rand. Untere Ecken sind frei, Minikarte in der Ecke, Hinweise lassen sich mit einem Kreuz schließen, das Ziel kann eingeklappt werden. Altes Layout: Einstellungen → Handy.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Hinweise (Pop-ups und Kurator) — ein Schalter in den Einstellungen. Wer du bist (Einheiten- oder Fahrzeugtyp) — Beschriftung „Du: …\" im HUD. Die Visiere von Gewehr und MG sind durchsichtig. Das Panel „Arsenal\" sitzt rechts, ist einklappbar und abschaltbar. „Allein ohne Trupp\" (J) wurde entfernt. Die Stimme des Strategen wiederholt nicht mehr dieselbe Zeile. Panzer erhalten eine Anzeige für Turm gegenüber Wanne. Der Cursor verschwindet am Anfang des Strategie-Trainings nicht mehr.",
