"Voice of hints & curator":"Stimme von Hinweisen & Kurator",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Handy: drei Stick-Modi. Nur links — „Auto\" (starker Magnet, schwächere Kugeln). Nur rechts — Zielen schaltet sich selbst ein, stärkerer Magnet, bessere Treffsicherheit. Beide — kein Zielen, schwächerer Magnet und Treffsicherheit. Die 👁-Taste rechts blendet das HUD aus/ein.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Handy: vereinfachte Strategie — nur Ingenieur und Gebäude. Karten links (Ingenieur, Hauptquartier, Kaserne …): Tippen — die Kamera fliegt hin, die untere Leiste zeigt, was gebaut/produziert werden kann. „In den Kampf\" — oben links. Die Armee kämpft von selbst. Volle Strategie — Einstellungen → Handy.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Übernehmen — zwei Schalter: „Trupps\" und „Fahrzeuge\" (auf Handys sind Fahrzeuge standardmäßig aus — die KI fährt sie). Bei ausgeschalteten Fahrzeugen: E (Handy: Taste rechts) neben einem eigenen Fahrzeug — Geschütz bemannen: Es fährt selbst, du schießt. Die alte eigene Klassenreihenfolge ist unter „Erweitert\". Eine Einheit antwortet per Funk, wenn du sie übernimmst.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Smarte Hinweise: Basis-Hinweise schalten sich nach dem 2. Start selbst ab, aber das Spiel weist auf eine Funktion hin, die du nie nutzt. Schalter: Basis / Fortgeschritten / Selten, getrennt — Stimme von Hinweisen und Kurator.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflex lädt sich durch Abschüsse auf (Serien laden stärker). Trupp-Kameraden zurückgefallen oder gefallen — der Stratege lässt neue bei dir landen (teurer als normaler Nachschub). Grafik und Ton von v7.2gfx sind integriert: wallende Explosionen, Rauch, Trümmer, Akustik von Schächten und Kratern. Das Build-Datum ist jetzt echt.",
