"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karriere und Spielstände bleiben unberührt. Im Kampf ist dasselbe Menü die Taste „🛠 Menü\" oben rechts{0}.",
"New developer match":"Neues Entwickler-Match",
"all unlocked, endless ore, instant build, arsenal":"alles freigeschaltet, endloses Erz, Sofortbau, Arsenal",
