"Cinema: everything built":"Kino: alles gebaut",
"both bases built and upgraded — for footage":"beide Basen gebaut und aufgerüstet — für Aufnahmen",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kino-Modus — Splitscreen: links der Strategen-Bot (Draufsicht auf Basis und Armee), rechts der Schützen-Bot in der Ego-Perspektive. Tasten unten (S, P): „Splitscreen“ und „★ Alles gebaut“ — beide Basen für Aufnahmen gebaut und aufgerüstet.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Der Kern und die Tunnel durch den Meteor sind weg — der Meteor ist massiv, gekämpft wird nur an der Oberfläche.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Handy: 👁 blendet das HUD aus, lässt aber Jetpack, ⇆, die Sticks und die Zielmarkierung stehen. „◎ Zielen“ (nur rechter Finger) — ein deutlich stärkerer und breiterer Magnet; die Magnetstärke für alle drei Modi — Einstellungen → Steuerung → „Erweitert“. Am Fahrzeuggeschütz heißt der Button „Absteigen“.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Training: Auf dem Handy nur Handy-Trainings, am PC nur PC-Trainings. Alle 4 sind im Menü „🛠 Entwickler“. Entwicklermodus und Arsenal sind jetzt ein Menü (im Kampf — „🛠 Menü“ oben rechts, am PC F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Grafikstile „Dendy (8-Bit)“ und „16-Bit“: Einstellungen → Grafik → „Grafikstil“ (Details — Button ⚙). Liegen die FPS in den ersten ~10 s eines Matchs unter 24, schaltet sich Dendy von selbst ein (darunter 20 — größere Pixel, 120 Zeilen); der Hinweis „Zurück zu normal“ stellt die normale Grafik dauerhaft wieder her. Deine eigene Wahl im Menü hat immer Vorrang.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D-Umgebungsmodelle (Ruinen, Wracks, Befestigungen) — nur gut bewertete, bei Bedarf gestreamt. Ausschalten: Einstellungen → Grafik → „Neue 3D-Umgebungsmodelle“.",
