"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"Stratege: Zielmarkierung ⌖ auf einer Feindansammlung, {0} m — Artillerieschlag in 8 Sekunden. Halte Abstand!",
