"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Soldaten können bauen: E (am Handy „Betreten“) an einer eigenen Baustelle — dein Soldat baut selbst, Truppkameraden in der Nähe helfen. Sind die Ingenieure beschäftigt, bittet dich der Stratege um Hilfe — Markierung „BAUSTELLE“.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Markierungen des Strategen: Der Stratege setzt ⌖ auf eine Feindansammlung in deiner Nähe — 8 s später schlägt dort die Artillerie ein, und eigene MLRS „Grad“ in der Nähe feuern eine Salve. Auch dein eigener Artillerieschlag aus dem Strategiemodus bekommt „Grad“-Unterstützung.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Waffenverstecke in Frachtcontainern und abgestürzten Satelliten (📦 sichtbar ab 70 m): E — ein schweres MG für 90 s, Brandmunition oder Raketen, dazu volle Granaten. Kriechen: Ctrl — hinlegen / aufstehen (tiefer, ruhiger, genauer, aber langsam).",
