"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Drei Stick-Modi am Handy, einfache Strategie, Fahrzeuggeschütz, Canyon-Gelände, Trupp-Klassen, Sprengstoff",
