"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"Gefällt dir die neue Version nicht — spiel die gewohnte. Die Wahl wird gespeichert; jede Version hat eigene Spielstände und Einstellungen (diese bleiben erhalten). Eine alte Version wird nur bei Auswahl geladen.",
