"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Jetzt spielen“ — der erste Menü-Button: ein kurzer Flug unter dem Himmelsportal und direkt in den Kampf (überspringen mit beliebiger Taste oder Tippen).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Treffer fühlen sich nach Treffern an: metallischer Klang und Funken, eine Abschussmarkierung am Fadenkreuz (Kopfschuss — gelb), eine Serie ×N, sanftes Wackeln bei Explosionen, Zeitlupe bei wichtigen Abschüssen. Wackeln, Zeitlupe und Hinweis lassen sich in den Einstellungen ausschalten.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Matchergebnis: Zeit, Abschüsse, beste Serie, ★ MVP und bester Trupp, eine Match-Karte — „⇪ Teilen“, PNG oder Link zum Spiel.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Ein Hinweis „Was jetzt zu tun ist“ links unter den Ressourcen: Befehl des Strategen, ein Kontrollpunkt zum Erobern, ein Angriff des Schwarms. ✕ oder F7 — einklappen.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Der Kampf wird automatisch gespeichert, wenn du den Tab schließt oder ausblendest — „⟲ Weiter“ im Menü.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 bleibt im Menü „🕘 Spielversion“, falls du sie lieber magst. Anonyme Statistik (ohne Namen oder E-Mail) wird jetzt gesendet; ausschalten in den Einstellungen.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Jetzt spielen“, Treffer-Feedback, Matchergebnis mit Teilen-Karte, Hinweis „Was tun“, Autospeichern",
"and older: v7.5, v7.4, milestones v1–v7.0":"und ältere: v7.5, v7.4, Meilensteine v1–v7.0",
"New in v7.6":"Neu in v7.6",
"NEW IN v7.6":"NEU IN v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Fraktionswahl vor dem Match: das „Konsortium“ (schwere Infanterie in Servorüstung, Panzerung und Artillerie) oder der „Schwarm“ (Tempo, Drohnenschwärme, schwere Schüsse mit Verzerrung). Die KI spielt die andere. Die Wahl wird gespeichert.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Jede Fraktion hat eigene Fahrzeuge und Besonderheiten: das Konsortium — den Panzer „Nashorn“ und „Keramit-Platten“, der Schwarm — „Drohnenschwarm“ und „Phasen-Jetpacks“. Balance mit Bot-Matches geprüft.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Explosionskrater: Artillerie, Raketen und Panzerkanonen graben Gruben in den Meteor — man kann hindurchgehen und -fahren und darin Deckung suchen.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Sicht aus der 3. Person für den Soldaten (V, wird gespeichert; am Handy — Steuerung) und eine sanfte Fahrzeugkamera mit Markierung, wo die Kanone trifft.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Version v7.6 bleibt im Menü „🕘 Spielversion“ — falls dir die neue nicht gefällt.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Fraktionen Konsortium / Schwarm mit Auswahl vor dem Match, Explosionskrater, Sicht aus der 3. Person",
