"dormant":"ruhend",
"Anomaly ahead! The vein is singing — go around!":"Anomalie voraus! Die Ader singt — wir umgehen sie!",
"Hear that hum? A singing vein. Keep clear!":"Hört ihr dieses Summen? Eine Singende Ader. Nicht näher kommen!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalie! Die Luft wirbelt — ein Strudel, geh drumherum!",
"Rocks floating in the air… A whirlpool! Stay out!":"Steine schweben in der Luft … Ein Strudel! Geh nicht rein!",
"Anomaly ahead — it is crackling with current!":"Anomalie voraus — es knistert vor Strom!",
"Rods and lightning — a Crackler. It loves armour!":"Stangen und Blitze — ein Knisterer. Er liebt Panzerung!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalie! Der Boden bebt vor Hitze — eine Feuerschale!",
"Careful, a Brazier underfoot!":"Vorsicht, unter deinen Füßen ist eine Feuerschale!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalie — grüner Nebel! Säure, nicht atmen!",
"The mist is drifting our way, go around!":"Der Nebel zieht auf uns zu, wir umgehen ihn!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalie! Die Luft ist wie Glas — eine Linse, sie krümmt Kugeln!",
"Everything is warping… a Lens nearby!":"Alles verzerrt sich … eine Linse in der Nähe!",
"Ha! An enemy walked right into the anomaly!":"Ha! Ein Feind ist direkt in die Anomalie gelaufen!",
"Got him! Lure them into anomalies!":"Erwischt! Lockt sie in Anomalien!",
"Beautiful zap! One less tin can.":"Schöner Blitz! Eine Blechbüchse weniger.",
"The anomaly got me!":"Mich hat die Anomalie erwischt!",
