"Clear, the anomaly is discharged.":"Sauber, die Anomalie ist entladen.",
"They say veins hide artifacts. Only first the vein sings…":"Man sagt, in den Adern verstecken sich Artefakte. Nur singt die Ader zuerst …",
"Throw a bolt first, then walk. Old habit.":"Wirf erst einen Bolzen, dann geh. Alte Gewohnheit.",
"throw a bolt":"Bolzen werfen",
