" — close":" — schließen",
"Supply drop":"Versorgungsabwurf",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Wirft eine Kiste bei deinen Truppen ab: Munition, Granaten, Raketen, Waffenteile, Reparaturset.",
"\"Grad\" rocket strike":"„Grad“-Raketenschlag",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 Raketen auf großes Gebiet nach 3 Sekunden — schneller und breiter als ein Artillerieschlag.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Unterstützung: Kiste, Aufklärung, „Grad“, Artillerieschlag (dann 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"ACHTUNG: „Grad“ des Schwarms auf euer Gebiet!",
"Warning! Rocket salvo on our position!":"Achtung! Raketensalve auf unsere Position!",
"take the supply crate":"Versorgungskiste nehmen",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalien auf dem Meteor (Welle 1): Die „Singende Ader“ — ein leuchtender grüner Kristall, der dröhnt und alle in der Nähe mit rhythmischen Impulsen trifft; der „Strudel“ zieht und schleudert, der „Knisterer“ schlägt Blitze zwischen Stangen, die „Feuerschale“ flammt unter den Füßen auf, der „Säurenebel“ und die „Linse“ (krümmt Kugeln und das Bild) treiben umher.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomalien spürt man schon vorher (Dröhnen, Leuchten, Hitzeflimmern). Entladen kannst du sie mit Granate, Rakete oder Bolzen (E an der Anomalie): Dann ruht sie und hinterlässt manchmal ein Artefakt mit Plus und Minus. Der Trupp warnt über Funk, und Feinde (und Verbündete) laufen manchmal hinein — lockt sie!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Unterstützung für Kommandopunkte (KP): 4 im Kampf (📡 am Handy) — Versorgungskiste, Aufklärung, „Grad“-Schlag, Artillerieschlag am Fadenkreuz. Der Stratege sieht Anomalien auf der Karte erst nach der Aufklärung.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Versorgungskisten in Ruinen alter Expeditionen, bei den Hauptquartieren und neben fertigen Gebäuden: Munition, Granaten, Raketen, Waffenteile (schalten Aufsätze frei).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Version v7.7 bleibt im Menü „🕘 Spielversion“. Anomalien lassen sich in den Einstellungen ausschalten.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalien (die „Singende Ader“ und 5 weitere), Entladen per Bolzen und Granate, Artefakte, Unterstützung für KP, Versorgungskisten",
"and older: v7.7, v7.6, milestones v1–v7.0":"und ältere: v7.7, v7.6, Meilensteine v1–v7.0",
"New in v7.8":"Neu in v7.8",
"NEW IN v7.8":"NEU IN v7.8",
"Close":"Schließen",
"Anomalies on the meteor":"Anomalien auf dem Meteor",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ in der Ecke öffnet das Pausenmenü: „Weiter“, „Neu starten“, „Training“, „Grafik“, „Einstellungen“, „Hauptmenü“ (mit Bestätigung). Handy: ☰ oben rechts (Kampfaktionen — die Kachel „⚡ Aktionen“); PC: Knopf „☰ Menü“ oben rechts oder Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Die Grafik ist standardmäßig immer normal — Dendy nur nach deiner Wahl: Der Schalter „Grafik: Normal / Dendy (8-Bit) / 16-Bit“ ist direkt im Hauptmenü und in der Pause. Wenn das Spiel stark ruckelt, erscheint ein Hinweis mit dem Knopf „Dendy aktivieren“.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Handy und Tablet: Der Aktionsknopf „✋“ rechts erscheint nur, wenn in der Nähe etwas zu tun ist — „Nehmen“ (Versteck, Kiste), „Einsteigen“ (Fahrzeug, Geschützturm, Geschütz), „Bauen“, „Absteigen“, „Bolzen“ an einer Anomalie. Du kannst auch einfach auf den hervorgehobenen Gegenstand tippen.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Handy, Strategie: Halte den Finger ~0,3 s (das Handy vibriert, ein gelber Ring erscheint) und zieh — ein Auswahlrahmen; normales Wischen bewegt die Kamera. Es gibt auch den Knopf „Rahmen“ rechts; im Training zählt beim Schritt „Rahmen“ auch das Antippen eines Trupps.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Handy: Winzige Knöpfe lassen sich leichter treffen, die Unterstützungsliste 📡 ist größer, Strategie-Panels überdecken Pause und Ergebnisse nicht mehr. Version v7.8 bleibt im Menü „🕘 Spielversion“.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"☰-Menü auf Handy und PC, kein Auto-Dendy, Knopf „✋“ am Handy, Auswahlrahmen am Handy",
"16-bit":"16-Bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Ruckelt es? Probier die Dendy-Grafik — sie ist leichter.",
"Turn on Dendy":"Dendy aktivieren",
"Use":"Aktion",
"Man gun":"Geschütz bemannen",
"Board":"Einsteigen",
"Man it":"Bemannen",
"Take":"Nehmen",
"and older: v7.8, v7.7, milestones v1–v7.0":"und ältere: v7.8, v7.7, Meilensteine v1–v7.0",
