"NEW IN v7.8.1":"NEU IN v7.8.1",
"Restart?":"Neu starten?",
"Quit to the main menu?":"Zum Hauptmenü verlassen?",
"The training starts from step one.":"Das Training beginnt beim ersten Schritt.",
"The current battle ends and a new match starts with the same settings.":"Der aktuelle Kampf endet und ein neues Match mit denselben Einstellungen beginnt.",
"Yes, restart":"Ja, neu starten",
"Yes, quit":"Ja, verlassen",
