"dash, redeploy…":"Sprint, Verlegung …",
"Restart":"Neu starten",
"Shooter":"Schütze",
"The Commander mode is not in the game yet":"Den Modus „Kommandant“ gibt es im Spiel noch nicht",
"Commander · soon":"Kommandant · bald",
"Commander — still in development":"Kommandant — noch in Entwicklung",
"Pause: resume, restart, training, graphics, settings, main menu":"Pause: weiter, neu starten, Training, Grafik, Einstellungen, Hauptmenü",
"Menu: pause, restart, training, graphics, settings":"Menü: Pause, neu starten, Training, Grafik, Einstellungen",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Halte den Finger ~0,3 s auf dem Boden — das Handy vibriert und ein gelber Ring erscheint — und zieh, ohne loszulassen: Es entsteht ein Rahmen. Oder nutze den Knopf „Rahmen“ rechts. Auch einfaches Antippen eines Trupps funktioniert.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Für Vollbild auf dem iPhone: „Teilen“ ⬆ → „Zum Home-Bildschirm“ — das Spiel öffnet sich ohne die Safari-Leisten.",
"Open portal-meteor.pages.dev for that.":"Öffne dafür die Seite portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Tippen — auswählen · Boden tippen — gehen · Lang drücken — Befehlsmenü · Lang drücken und ziehen — Rahmen · 2 Finger — Zoom",
"Robo-ninja":"Robo-Ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Assassinen-Heldin: Blink-Sprints, Katana, Shuriken. Springt selbstständig durch Feindzonen und zerschneidet Roboter. 1 pro Seite.",
"Shadow protocol":"Protokoll „Schatten“",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Forschung: schaltet die Robo-Ninja in der Kaserne frei. Benötigt eine fertige Mech-Fabrik.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Heldin (1 pro Seite): teleportiert sich selbstständig durch Feindzonen und zerschneidet Roboter; übernimm sie, um manuell zu spielen.",
"is ready. She works on her own (AUTO) — possess her to play manually":"ist bereit. Sie arbeitet selbstständig (AUTO) — übernimm sie, um manuell zu spielen",
