"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-Ninja: ein Cyborg mit Katana. Wird in der Kaserne durch die Forschung „Schattenprotokoll“ freigeschaltet (benötigt eine Mech-Fabrik). Teleportiert sich selbstständig in Feindzonen, zerschneidet Gegner (kein Blut — Funken), Blinks, Shuriken, Duelle mit der gegnerischen Ninja. Übernimm sie — AUTO-Modus oder manuelle Steuerung (am Handy mit eigenen Tasten).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 EDMITRY-Tracks direkt im Spiel. Taste 5 (umbelegbar), am Handy — ☰ → Einstellungen → Ton. Lautstärke und „im Kampf automatisch starten“ findest du in den Einstellungen; die Musik wird bei Explosionen und Funksprüchen leiser.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Neue Sprachen: Usbekisch und Tadschikisch — vollständig; Chinesisch, Spanisch, Portugiesisch — teilweise. Neue Sprachauswahl im Menü neben „Neues Match“.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Handy: „Symbole ausblenden“ 👁 sammelt die übrigen Tasten in einer ordentlichen Spalte am rechten Rand; Hochformat überlappt nicht mehr; iPhone — das Spiel kollidiert nicht mehr mit Safari-Gesten, und „Teilen → Zum Home-Bildschirm“ startet es im Vollbild.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Aus v7.8.1: ☰-Eckmenü (Pause, Neustart, Training, Grafik), kein Auto-Dendy, ✋-Aktionstaste am Handy. v7.8.1 und v7.8 bleiben im Menü „🕘 Spielversion“.",
