"Select a unit → \"▶ Possess\" or double-tap. Mode button at the top right: Strategist → Commander → Shooter.":"Wähle eine Einheit → „▶ Übernehmen“ oder Doppeltipp. Modustaste oben rechts: Stratege → Kommandant → Schütze.",
"Select a unit → \"▶ Possess\" or double-click. {0} cycles: Strategist → Commander → Shooter.":"Wähle eine Einheit → „▶ Übernehmen“ oder Doppelklick. {0} wechselt im Kreis: Stratege → Kommandant → Schütze.",
