"Living world: requests, hero quests, breakthrough ops":"Lebendige Welt: Bitten der Eigenen, Heldenquests, Wendepunkt-Operationen",
"Living world":"Lebendige Welt",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Deine Einheiten bitten um Hilfe und belohnen dich, Helden geben Quests, eine festgefahrene Front wird mit einer Operation aufgebrochen",
"A request":"Eine Bitte der Eigenen",
"Breakthrough":"Wendepunkt",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Deine Einheiten bitten manchmal um Hilfe: eine Stimme im Funk, eine BITTE-Karte und eine ✋-Markierung. Ein Trupp ist festgenagelt — vernichte die Feinde in seiner Nähe. Belohnung: ein Soldat per Kapsel von der Basis, eine Waffe aus dem Buggy-Kofferraum, der Schützenplatz oder Orbitaldeckung. Gerade nicht — ✕ oder einfach ignorieren.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Der Veteran und Späher „Eule“ bietet einen Quest an. Y — annehmen (N — ablehnen). Geh zur ★-Markierung, schalte die Wachen aus und bleib 3 s beim Piloten — er schließt sich deinem Trupp an.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Die Front steckt fest — das Hauptquartier bietet einen Wendepunkt an. Y — annehmen. Halte das Relais 8 s lang ohne Feinde in der Nähe: Die feindliche Karte ist 60 s sichtbar. Der Generator — feindliche Geschütztürme schweigen 2 Min. Im Modus Stratege — „Trupp beauftragen“. Der Feind kann das auch: Achte auf ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Deine Einheiten bitten um Hilfe: eine BITTE-Karte und eine ✋-Markierung. Vernichte die Feinde beim festgenagelten Trupp — du bekommst eine Belohnung. ✕ — überspringen.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Der Held „Eule“ bietet einen Quest an — tippe auf „Annehmen“. Geh zu ★, schalte die Wachen aus, bleib beim Piloten.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Die Front steckt fest — tippe auf „Annehmen“ und halte das Relais 8 s lang: Die feindliche Karte öffnet sich für eine Minute.",
