"Builds structures and extractors, repairs, cleans Steel fluff off others.":"Baut Gebäude und Extraktoren, repariert, entfernt Stahlflaum von Verbündeten.",
"A squad flies from the base launch pad through the sky portal right to the target.":"Ein Trupp fliegt von der Startrampe der Basis durch das Himmelsportal direkt zum Ziel.",
"Squad: ":"Trupp: ",
"Engineer":"Ingenieur",
"Members: ":"Besatzung: ",
"Main battle tank: cannon and MG. Consortium \"Bulldog\" is tougher, Swarm \"Spider\" is faster.":"Standard-Kampfpanzer: Kanone und MG. Der „Bulldogge“ des Konsortiums ist zäher, die „Spinne“ des Schwarms schneller.",
"Heavy tank":"Schwerer Panzer",
"Autonomous flying gunner: fast, fragile, fears anti-air.":"Autonomer fliegender Schütze: schnell, zerbrechlich, fürchtet Flak.",
"Upgrade":"Verbesserung",
"Longer, faster jetpacks for all infantry.":"Jetpacks mit mehr Reichweite und Tempo für die gesamte Infanterie.",
"Extractors mine more ore.":"Extraktoren fördern mehr Erz.",
"Army-wide levels: less damage taken / more damage dealt.":"Armeeweite Stufen: weniger erlittener / mehr verursachter Schaden.",
"Levels":"Stufen",
"Base":"Basis",
"Heart of the base: squads, engineers, pods, research. Lose it and you lose.":"Herz der Basis: Trupps, Ingenieure, Kapseln, Forschung. Geht es verloren, verlierst du.",
"Produces: ":"Produziert: ",
"Launch pad":"Startrampe",
"A silo next to the HQ: pods, supply crates and bombers launch from here through the sky portal. Nothing can be built on it.":"Ein Silo neben dem Hauptquartier: Von hier starten Kapseln, Versorgungskisten und Bomber durch das Himmelsportal. Darauf kann nicht gebaut werden.",
"Economy":"Wirtschaft",
"Key building":"Schlüsselgebäude",
"Weak spot — the rear (engine): damage ×{0}. Cannon, 2 MG turrets, rocket pod; turns very slowly — flank it.":"Schwachstelle — das Heck (Motor): Schaden ×{0}. Kanone, 2 MG-Türmchen, Raketenwerfer; dreht sehr langsam — greif von der Seite an.",
"Weak spot — the glowing core underneath: damage from below ×{0}. Distortion beam and area stomp; steps over barriers — keep distance, don't bunch up.":"Schwachstelle — der leuchtende Kern am Bauch: Schaden von unten ×{0}. Verzerrungsstrahl und Flächenstampfer; steigt über Barrieren — halte Abstand und steh nicht dicht gedrängt.",
"Counter: bombs and artillery (×{0}), rockets (×{1}), carpet bombing; bullets barely scratch it (×{2}).":"Konter: Fliegerbomben und Artillerie (×{0}), Raketen (×{1}), Flächenbombardement; Kugeln kratzen kaum (×{2}).",
"Faction":"Fraktion",
"Fast machines, drone packs, tunnels and regeneration. Lighter but faster infantry; cannons and rails hit harder.":"Schnelle Maschinen, Drohnenschwärme, Tunnel und Regeneration. Leichtere, aber schnellere Infanterie; Kanonen und Schienen treffen härter.",
"Heavy power-armoured infantry, concrete barriers, repair and artillery. Slower but tougher.":"Schwere Infanterie in Kampfpanzerung, Betonbarrieren, Reparatur und Artillerie. Langsamer, aber zäher.",
"Infantry HP":"Infanterie: Haltbarkeit",
"Infantry speed":"Infanterie: Tempo",
"Jetpacks":"Jetpacks",
"Weapon damage: ":"Waffenschaden: ",
