"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Spiel und denk laut: was unklar ist, was nervt, was Spaß macht. Die Ecke zeigt Version, Zeit und FPS — damit wird die Aufnahme mit den Notizen abgeglichen.",
