"you fight yourself":"du kämpfst selbst",
"you lead one squad":"du führst einen Trupp",
"you command the whole army from above":"du befehligst die ganze Armee von oben",
"Want to command the army?":"Willst du die Armee befehligen?",
"Unlock the Strategist mode: look from above and give orders to the whole army.":"Schalte den Modus „Stratege“ frei: Du siehst von oben und gibst der ganzen Armee Befehle.",
"Want to lead one squad?":"Willst du einen Trupp führen?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Schalte den Modus „Kommandant“ frei: Kamera über dem Trupp, Tippen — wohin es geht.",
"Yes":"Ja",
"Later":"Später",
"You run and shoot yourself. That is how you have played so far.":"Du rennst und schießt selbst. So hast du bisher gespielt.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Du siehst von oben und befehligst die ganze Armee: baust die Basis, schickst Trupps los. Die Armee kämpft auch ohne dich von allein.",
"You lead one squad: the camera is above it, tap the ground to move.":"Du führst einen Trupp: Die Kamera ist darüber, Tippen auf den Boden — wohin es geht.",
"The mode button is at the top right: tap for the next mode.":"Die Modustaste ist oben rechts: Tippen — nächster Modus.",
