"Third-person view — tap 🎥 to go back":"Ansicht aus der 3. Person — tippe auf 🎥, um zurückzukehren",
"Third-person view — {0} to go back":"Ansicht aus der 3. Person — {0}, um zurückzukehren",
"the gamepad view button or ":"die Ansichtstaste am Gamepad oder ",
"key ":"Taste ",
"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Hinweis eingeklappt — mit „?“ öffnest du ihn wieder. Lektion verlassen: ☰ → „Lektion verlassen“",
"◎ precise":"◎ präzise",
"○ running":"○ Rennen",
"◉ run + aim":"◉ Rennen + Zielen",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"Modus „Kommandant“, Fraktionsbosse, lebendiger Meteor (Gelände, Biome, Wetter, Anomalien, Fauna), lebendige Welt; schneller, Gamepad, Tablet, Enzyklopädie, Feedback-Modus, einfache Handy-Oberfläche",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Drei Modi auf einer Taste: Schütze (du kämpfst selbst), der neue Kommandant (du führst einen Trupp, 4 Fähigkeiten pro Einheitentyp) und Stratege. Auf dem Handy — eine einfache Oberfläche: weniger Tasten, die Modi werden im Laufe des Kampfes freigeschaltet.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Lebendiger Meteor: Felsen, Bergkämme, ein Hangar im Tafelberg, Seen aus Lava, Eis und Methan, drei Biome, lokales Wetter, neue Anomalien und einheimische Fauna.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Die Fraktionen spielen sich jetzt unterschiedlich: Der Schwarm gräbt Tunnel und regeneriert, das Konsortium stellt Barrieren auf und repariert. Ab Minute 12 — die Bosse „Bastion“ und „Reaper“; in den eigenen kannst du dich einnisten.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Lebendige Welt: Deine Soldaten bitten per Funk um Hilfe (mit Belohnung), Helden geben Aufträge, bei festgefahrener Front gibt es die Operation „Durchbruch“. Kapseln, Kisten und Schläge starten von der Basis durch das Himmelsportal.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Schneller (ein Frame bis zu 2× günstiger), Gamepad in allen Modi, Tablet-Layout, eine Enzyklopädie von allem im Spiel, Feedback-Modus — eine Notiz mit Screenshot auf einer Taste.",
